//! The wire constants as an ECMAScript module (`web/protocol_constants.mjs`).

use super::{
    ActionCode, AttachmentKey, DiagnosticCode, ErrorCategory, FitCode, OpenFlags, OutlineStyle,
    PositionKind, RequestKind, ResponseKind, SearchFlags, TileStatus, Version,
};
use crate::SessionLimits;
use crate::editing;
use crate::reading::{
    MAX_ATTACHMENTS, MAX_PAGE_CHARACTERS, MAX_QUERY_BYTES, MAX_SEARCH_MATCHES, MAX_SEARCH_PAGES,
};
use pagura::Limits;
use std::fmt::{self, Write};

const HEADER: &str = "\
// Generated by `cargo run -p pagura-host --features codegen --example
// protocol_constants` from the wire tables in
// crates/pagura-host/src/protocol/codes.rs and the default session budgets.
// Do not edit: the pagura-host test `protocol_constants` fails when this file
// differs from what the Rust code generates.
";

/// A name, its doc comment and its value or `(key, value)` entries.
type Item<T> = (&'static str, &'static str, T);

/// The entries of a wire enum, keyed by variant name.
macro_rules! codes {
    ($codes:ty) => {
        <$codes>::ALL
            .iter()
            .map(|code| (code.name(), code.code().to_string()))
            .collect()
    };
}

/// The entries of a bit field, keyed by flag name.
macro_rules! flags {
    ($flags:ty) => {
        <$flags>::ALL
            .iter()
            .map(|(name, flag)| (*name, flag.bits().to_string()))
            .collect()
    };
}

/// The protocol's code tables and default budgets as an ECMAScript module,
/// the content of the checked-in `web/protocol_constants.mjs`.
///
/// Each code space is a frozen object named after its Rust enum, with the
/// variant names as keys. `MAX_FRAME` is [`SessionLimits::max_frame_bytes`]
/// under `Limits::default()`.
pub(crate) fn javascript_constants() -> String {
    let mut out = String::from(HEADER);
    // Writing to a `String` cannot fail.
    let _ = write_module(&mut out);
    out
}

fn write_module(out: &mut String) -> fmt::Result {
    for (name, doc, entries) in tables() {
        writeln!(
            out,
            "\n/** {doc} */\nexport const {name} = Object.freeze({{"
        )?;
        for (key, value) in entries {
            writeln!(out, "  {key}: {value},")?;
        }
        writeln!(out, "}});")?;
    }
    for (name, doc, value) in numbers() {
        writeln!(out, "\n/** {doc} */\nexport const {name} = {value};")?;
    }
    Ok(())
}

fn tables() -> [Item<Vec<(&'static str, String)>>; 13] {
    let versions = Version::ALL
        .iter()
        .map(|version| (version.name(), format!("{:#010x}", version.code())))
        .collect();
    [
        (
            "Version",
            "Protocol versions, negotiated by hello.",
            versions,
        ),
        ("RequestKind", "Request kind bytes.", codes!(RequestKind)),
        ("ResponseKind", "Response kind bytes.", codes!(ResponseKind)),
        (
            "AttachmentKey",
            "Explicit embedded-file filename keys (1.8).",
            codes!(AttachmentKey),
        ),
        (
            "ErrorCategory",
            "Error categories of response kind 255.",
            codes!(ErrorCategory),
        ),
        (
            "DiagnosticCode",
            "Kinds of typed diagnostic records (1.4).",
            codes!(DiagnosticCode),
        ),
        (
            "PositionKind",
            "Position kinds of an error or diagnostic context.",
            codes!(PositionKind),
        ),
        (
            "OpenFlags",
            "Flag bits of an open request.",
            flags!(OpenFlags),
        ),
        (
            "TileStatus",
            "Status bytes of a generated tile (1.1).",
            codes!(TileStatus),
        ),
        (
            "FitCode",
            "Destination fit bytes (ISO 32000-2 Table 149).",
            codes!(FitCode),
        ),
        (
            "ActionCode",
            "Target action type bytes.",
            codes!(ActionCode),
        ),
        (
            "SearchFlags",
            "Search option bits (1.2).",
            flags!(SearchFlags),
        ),
        ("OutlineStyle", "Outline style bits.", flags!(OutlineStyle)),
    ]
}

fn numbers() -> [Item<String>; 12] {
    let engine = Limits::default();
    let session = SessionLimits::default();
    [
        (
            "MAX_FRAME",
            "Largest frame body: max(file_bytes + string_bytes + 14, pixels * 4 + 18,\n *  reading_response_bytes + 5, 1024) under the default limits, at most u32::MAX.",
            session.max_frame_bytes.to_string(),
        ),
        (
            "MAX_FILE",
            "Largest PDF in an open request (Limits::file_bytes).",
            engine.file_bytes.to_string(),
        ),
        (
            "MAX_PASSWORD",
            "Largest password in an open request (Limits::string_bytes).",
            engine.string_bytes.to_string(),
        ),
        (
            "MAX_READING_RESPONSE",
            "Largest reading response payload.",
            session.reading_response_bytes.to_string(),
        ),
        (
            "MAX_QUERY_BYTES",
            "Largest search query in UTF-8 bytes.",
            MAX_QUERY_BYTES.to_string(),
        ),
        (
            "MAX_SEARCH_MATCHES",
            "Most matches in one search response.",
            MAX_SEARCH_MATCHES.to_string(),
        ),
        (
            "MAX_SEARCH_PAGES",
            "Most pages in one search window.",
            MAX_SEARCH_PAGES.to_string(),
        ),
        (
            "MAX_PAGE_CHARACTERS",
            "Most semantic characters in one page text response.",
            MAX_PAGE_CHARACTERS.to_string(),
        ),
        (
            "MAX_ATTACHMENTS",
            "Most catalog attachments in one listing (1.8).",
            MAX_ATTACHMENTS.to_string(),
        ),
        (
            "MAX_FORM_FIELDS",
            "Most form fields in one inspection or save (1.5).",
            editing::MAX_FIELDS.to_string(),
        ),
        (
            "MAX_FORM_OPTIONS",
            "Most choice options and button states in one form inspection (1.5).",
            editing::MAX_OPTIONS.to_string(),
        ),
        (
            "MAX_FORM_BYTES",
            "Largest form change payload and form response (1.5).",
            engine.document_bytes.min(editing::MAX_BYTES).to_string(),
        ),
    ]
}

#[cfg(test)]
mod tests {
    use pagura_testkit::workspace_root;

    /// The checked-in module is what the wire tables generate, so the web
    /// client cannot drift from the host.
    #[test]
    fn protocol_constants() {
        let path = workspace_root().join("web/protocol_constants.mjs");
        let checked_in = std::fs::read_to_string(&path).unwrap();
        assert!(
            checked_in == super::javascript_constants(),
            "{} differs from the Rust wire tables; regenerate it with\n  \
             cargo run -p pagura-host --features codegen --example protocol_constants \
             > web/protocol_constants.mjs",
            path.display()
        );
    }
}
